/// Categories of smart reminders and local notifications generated by YeeTrip.
enum AppNotificationType {
  tripStart,
  budgetAlert,
  settlementReminder,
  itineraryUpcoming,
}

/// Severity/urgency of an in-app or OS notification.
enum AppNotificationSeverity {
  info,
  warning,
  critical,
}

/// Pure Dart representation of a smart trip notification / reminder.
class AppNotificationItem {
  final String id;
  final String tripId;
  final String tripName;
  final AppNotificationType type;
  final AppNotificationSeverity severity;
  final String title;
  final String body;
  final DateTime timestamp;
  final String? actionRoute;
  final bool isRead;

  const AppNotificationItem({
    required this.id,
    required this.tripId,
    required this.tripName,
    required this.type,
    this.severity = AppNotificationSeverity.info,
    required this.title,
    required this.body,
    required this.timestamp,
    this.actionRoute,
    this.isRead = false,
  });

  AppNotificationItem copyWith({
    bool? isRead,
  }) {
    return AppNotificationItem(
      id: id,
      tripId: tripId,
      tripName: tripName,
      type: type,
      severity: severity,
      title: title,
      body: body,
      timestamp: timestamp,
      actionRoute: actionRoute,
      isRead: isRead ?? this.isRead,
    );
  }
}

/// User notification preferences persisted in SharedPreferences.
class NotificationPreferences {
  final bool tripStartReminders;
  final bool budgetBurnAlerts;
  final bool settlementReminders;
  final bool itineraryReminders;

  const NotificationPreferences({
    this.tripStartReminders = true,
    this.budgetBurnAlerts = true,
    this.settlementReminders = true,
    this.itineraryReminders = true,
  });

  NotificationPreferences copyWith({
    bool? tripStartReminders,
    bool? budgetBurnAlerts,
    bool? settlementReminders,
    bool? itineraryReminders,
  }) {
    return NotificationPreferences(
      tripStartReminders: tripStartReminders ?? this.tripStartReminders,
      budgetBurnAlerts: budgetBurnAlerts ?? this.budgetBurnAlerts,
      settlementReminders: settlementReminders ?? this.settlementReminders,
      itineraryReminders: itineraryReminders ?? this.itineraryReminders,
    );
  }
}
